from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=max({v for row in grid for v in row},key=lambda v:sum(row.count(v) for row in grid))
    seen=set(); fill=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg or (r,c) in seen: continue
            q=deque([(r,c)]);seen.add((r,c));comp=[]
            while q:
                y,x=q.popleft();comp.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==bg and (ny,nx) not in seen:
                        seen.add((ny,nx));q.append((ny,nx))
            r0=min(y for y,x in comp);r1=max(y for y,x in comp)
            c0=min(x for y,x in comp);c1=max(x for y,x in comp)
            hh,ww=r1-r0+1,c1-c0+1
            rectangular=len(comp)==hh*ww
            edge=[(y,x) for y,x in comp if y in (0,h-1) or x in (0,w-1)]
            enclosed=not edge and rectangular
            if edge and rectangular and hh>=2 and ww>=2:
                sides=set()
                if any(y==0 for y,x in edge):sides.add('top')
                if any(y==h-1 for y,x in edge):sides.add('bottom')
                if any(x==0 for y,x in edge):sides.add('left')
                if any(x==w-1 for y,x in edge):sides.add('right')
                corners={(0,0),(0,w-1),(h-1,0),(h-1,w-1)}
                if len(sides)==1 and not any(p in corners for p in edge):
                    enclosed=True
            if enclosed:fill.update(comp)
    return [[4 if (r,c) in fill else grid[r][c] for c in range(w)] for r in range(h)]
